import networkx as nx
import itertools

def find_graph():
    for edges in itertools.combinations(range(12), 2):
        G = nx.Graph()
        G.add_nodes_from(range(12))
        G.add_edges_from(edges)
        G.add_edges_from([(5,7), (4,6)])
        if all(degree >= 1 for degree in (G.degree(node) for node in G.nodes())):
            if all(degree <= 2 for degree in (G.degree(node) for node in G.nodes())):
                if len(edges) >= 9 and len(edges) <= 11:
                    if nx.algorithms.coloring.greedy_color(G) <= 2:
                        if nx.algorithms.coloring.greedy_color(G) >= 2:
                            return list(G.edges)
    return "UNSATISFIABLE"

print(find_graph())
